function L({registerIndicator:P,sourceValues:x,nulls:h}){const u=t=>{const c=1.414*Math.PI/t,r=Math.cos(c);if(!Number.isFinite(r)||r===0)return null;const n=(r+Math.sin(c)-1)/r,l=1-n*.5,o=1-n;return{a1:l*l,b1:2*o,c1:-(o*o)}};P({id:"oa-deco",name:"Ehlers Decycler Oscillator (DECO)",category:"Oscillators",placement:"pane",inputs:[{key:"shortPeriod",type:"number",label:"Short Period",default:30,min:1,max:500,step:1,tooltip:"Short cycle cutoff period for high-pass filter."},{key:"longPeriod",type:"number",label:"Long Period",default:60,min:2,max:1e3,step:1,tooltip:"Long cycle cutoff period for high-pass filter."},{key:"source",type:"source",label:"Source",default:"close",tooltip:"Price series to analyze."}],plots:[{key:"deco",type:"line",title:"DECO",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero Line",color:"#787b86",dashed:!0}],calc(t,c){const r=Math.max(1,Math.floor(Number(c.shortPeriod)||30)),n=Math.max(2,Math.floor(Number(c.longPeriod)||60)),l=x(t,c.source??"close"),o=new Array(t.length).fill(NaN);if(r>=n)return{deco:h(o)};const i=u(r),s=u(n);if(!i||!s)return{deco:h(o)};const a=new Array(t.length);for(let e=0;e<t.length;e++)a[e]=Number.isFinite(l[e])?l[e]:0;let f=0,d=0,p=0,m=0;for(let e=0;e<t.length;e++){const M=e>=1?a[e-1]:0,N=e>=2?a[e-2]:0,y=a[e]-2*M+N,b=e<2?0:i.a1*y+i.b1*f+i.c1*d,g=e<2?0:s.a1*y+s.b1*p+s.c1*m;d=f,f=b,m=p,p=g,Number.isFinite(l[e])&&(o[e]=g-b)}return{deco:h(o)}}})}export{L as default};
